  ],
  stream: false,
  format: { type: 'object', required: ['testStrategyMarkdown','testScenariosMarkdown'], properties: { testStrategyMarkdown: { type: 'string' }, testScenariosMarkdown: { type: 'string' } } },
  options: { temperature: $('Initialize Parameters').first().json.ollamaTemperature, seed: $('Initialize Parameters').first().json.ollamaSeed }
} }}

