const raw = $json.message?.content;
let p; try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, error: 'JSON parse failed' } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const valid = p.testStrategyMarkdown && p.testStrategyMarkdown.startsWith('# Test Strategy:');
return [{ json: { valid, testStrategyMarkdown: p.testStrategyMarkdown || '', testScenariosMarkdown: p.testScenariosMarkdown || '', hashes: { strategy: fnv1a(p.testStrategyMarkdown), scenarios: fnv1a(p.testScenariosMarkdown) } } }];

const j = $json;
if (!j.valid) return [];
const ctx = $('Pass Context').first().json;
const meta = { jobId: ctx.jobId, stage: 'test-strategy' };
const out = [];
out.push({ json: { artifactType: 'test_strategy_md', content: { markdown: j.testStrategyMarkdown }, contentHash: j.hashes.strategy, meta } });
out.push({ json: { artifactType: 'test_scenarios_md', content: { markdown: j.testScenariosMarkdown }, contentHash: j.hashes.scenarios, meta } });
return out;

const ctx = $('Pass Context').first().json;
