  if (!content) return '';
  return String(content).replace(new RegExp(marker, 'g'), marker + '_ESCAPED');
};

let sh = `set -e
mkdir -p /opt/workspace

if [ ! -d '${repoDir}/.git' ]; then
  git clone '${remote}' '${repoDir}'
fi
cd '${repoDir}'
git fetch origin --prune

git checkout -B '${projectSlug}' 'origin/${projectSlug}' 2>/dev/null || git checkout -B '${projectSlug}'
mkdir -p '${projectDir}/docs'
`;

// Test Strategy
sh += `cat > '${projectDir}/docs/test-strategy.md' <<'EOFSTRAT_${jobId}'
${safeHeredoc(qa.testStrategyMarkdown, 'EOFSTRAT_' + jobId)}
EOFSTRAT_${jobId}
`;

// Test Scenarios
sh += `cat > '${projectDir}/docs/test-scenarios.md' <<'EOFSCEN_${jobId}'
${safeHeredoc(qa.testScenariosMarkdown, 'EOFSCEN_' + jobId)}
EOFSCEN_${jobId}
`;

sh += `
git add '${projectSlug}-docs'
git commit -m 'Add test strategy and scenarios for ${projectSlug} (job ${jobId})' || true
git push -u origin '${projectSlug}'
`;

return [{ json: { ...ctx, gitScript: sh } }];

